task sum_Square(n: int) returns (r: bool)
  ensures r == (exists a b: a * a + b * b == n)
{
  r := false;
  var i: int := 0;
  while i * i < n
    invariant i >= 0
    invariant i * i <= n
    invariant r == (exists a b: a * a + b * b == n and a <= i)
    decreases n - i * i
  {
    var j: int := 0;
    while j * j <= n - i * i
      invariant j >= 0
      invariant j * j <= n - i * i
      invariant r == (exists a b: a * a + b * b == n and a <= i and b <= j)
      decreases n - i * i - j * j
    {
      if i * i + j * j == n {
        r := true;
        return r;
      }
      j := j + 1;
    }
    i := i + 1;
  }
}
